for q,ans,order in [('H30-REG-APPLIED-04',3,[0,1,2,3,4]),('R04-REG-APPLIED-03',4,[1,0,3,2,4])]:
 vals=['クーロンの法則','プランクの法則','ビオ・サバールの法則','ファラデーの誘導法則','キュリー・ワイスの法則'];reasons=['点電荷の静電気力を与え、電流素片の磁場ではない。','黒体の熱放射スペクトルの法則である。','定常電流素片Idℓから磁束密度dBを与える法則である。','磁束の時間変化による誘導起電力を与える。','磁性体の磁化率の温度依存を扱う。']
 add(q,'小さな電流素片が作る磁場を与える法則名を選ぶ。',{'対象':'定常電流の微小素片が作る磁場。'},[vals[i] for i in order],[reasons[i] for i in order],ans,'微小素片の寄与は'+m(r'dB=\mu_0 I(d\ell\times\hat r)/(4\pi r^2)')+'というビオ・サバールの法則で与えられ、'+str(ans)+'である。素片を積分して導線全体の場を求める。誘導起電力の法則と、電流を源とする場の法則を区別する。','電流素片から磁場を作る法則','定常電流、外積、重ね合わせ、磁束の時間変化との違い。',['biot'],concept='concept_038',citations=['mit_em09'])
add('R01-REG-APPLIED-03','電流の定義、向き、磁場、単位の4空欄の組合せを選ぶ。',{'A':'電流が表す何の流れか。','B':'電流方向と逆に移動するAの符号。','C':'電流方向に対する、直線電流の周囲の磁場方向。','D':'アンペアの表現。','並び':'A／B／C／D。'},['原子／負／垂直／C/s','電子／正／垂直／C/s','イオン／正／平行／C/m²','電荷／負／平行／C/m²','電荷／負／垂直／C/s'],['電流は一般に電荷の流れで、原子に限定されない。','電子は負であり、正の電子が逆方向へ進むという表現は合わない。','正電荷の移動方向は電流方向と同じで、磁場と単位も違う。','最初の二語は合うが、直線電流の磁場は周方向で電流へ垂直、単位はC/sである。','電荷の流れ、負の移動と逆向き、垂直、C/sの4条件が全て合う。'],5,'電流は電荷の移動を数える。正電荷の移動方向を正とするため、負電荷の移動と電流は逆向きになる。直線電流の周囲の磁場は電流を囲む円周方向、1 A=1 C/sで5を選ぶ。電流の担い手を電子だけへ限定しない。','電流の符号規約と単位','電荷輸送、正負の担い手、右ねじ、アンペア。',['dc','biot'],concept='concept_039',figure=True,citations=['mit_em06','mit_em09'])
add('R01-REG-APPLIED-04','電磁気の基本法則の説明で、最も不適切なものを選ぶ。',{'注意':'③の原典は二箇所とも電束と記す。磁束へ書き換えて読まない。','方向':'最も不適切。'},['閉曲面を貫く電束は内部の真電荷の量に等しく、電場のガウス法則である。','ビオ・サバールの法則は定常電流が作る磁場を決める。','閉回路を貫く電束が変化すると、電束変化を妨げる起電力が生じることをファラデーの法則という。','領域の総電荷の時間変化は閉曲面を通じた電荷の正味の出入りと対応し、電気量保存を表す。','マクスウェル方程式は電磁場の基本方程式で19世紀に提出された。'],['Dの閉曲面電束を内部真電荷へ対応させる説明である。','電流素片から場を積分する定常磁場の法則である。','誘導起電力は磁束の変化に対応する。電束変化はアンペール・マクスウェルの変位電流側の量である。','外向き電流を正に取ればdQ/dt=−∫i·n dSである。原典の出入りは符号付きの正味量として読む。','マクスウェルが19世紀に電磁気の法則をまとめたという説明に合う。'],3,'3の決め手は原典の「電束」である。ファラデーの法則は'+m(r'\mathcal E=-d\Phi_B/dt')+'と磁束を用いる。電束変化による変位電流と混同しているため3を選ぶ。保存則の「出入り」は流入を正にした正味量として区別する。','電束の変化と磁束の変化','ガウス、ビオ・サバール、ファラデー、連続の式、変位電流。',['induction','maxwell'],concept='concept_038',verdicts=['適切','適切','不適切','適切','適切'],citations=['mit_em10','mit_em13'])
add('R01-RET-APPLIED-06','直流回路と抵抗の説明で、最も不適切なものを選ぶ。',{'対象':'定常直流、真性半導体、純金属の抵抗。','方向':'最も不適切。'},['二点間の電位差はどの経路で測っても同じである。','真性半導体では温度上昇で電気抵抗が減る。','純金属に少量の不純物を混ぜると抵抗は増える。','多くの導体の抵抗率は温度の二乗に比例する。','消費電力は単位時間あたり消費するエネルギーである。'],['静電的・定常直流の近似では電位は一価な関数であり経路に依存しない。','熱励起により担い手が増え、真性領域では抵抗が減る。','不純物による電子散乱が増え、残留抵抗等が大きくなる。','室温近傍の金属では基準温度からの変化を一次近似することが多い。特定低温域のT²項を多くの導体の一般則にできない。','P=dW/dtであり、単位J/s=Wである。'],4,'4は材料と温度域を限定せず二乗比例を一般則とする点が誤りである。金属の室温近傍では'+m(r'\rho(T)\simeq\rho(T_0)[1+\alpha(T-T_0)]')+'と近似し、真性半導体では担い手の熱励起が支配する。低温でT²項が現れる場合まで否定するのではない。','抵抗の温度依存と材料の区別','金属の散乱、残留抵抗、真性キャリア、近似の温度範囲。',['resistivity','potential'],concept='concept_039',verdicts=['適切','適切','適切','不適切','適切'],citations=['mit_em06','mit_semiconductor'])
add('R04-REG-APPLIED-04','充電したコンデンサーを抵抗0のコイルへ接続し、最大電流時のコイルエネルギーを求める。',{'容量':'2.0×10⁻¹⁰ F','初期電圧':'5.0 V','インダクタンス':'5.0×10⁻³ H','抵抗':'0。理想LC振動。'},['0 J',m(r'1.3\times10^{-9}')+' J',m(r'2.5\times10^{-9}')+' J',m(r'5.0\times10^{-9}')+' J',m(r'7.5\times10^{-9}')+' J'],['最大電流時はコイルの磁場エネルギーが最大であり0でない。','初期エネルギーの約半分だが、最大電流では電気エネルギーは0となり全量が磁気側へ移る。','初期のCV²/2=2.5×10⁻⁹ Jに一致する。','係数1/2を落としたCV²の値である。','保存される初期エネルギーの3倍である。'],3,'抵抗0なので全エネルギー'+m(r'Q^2/(2C)+LI^2/2')+'は一定である。電流最大時はQ=0、初期の'+m(r'CV_0^2/2=(2.0\times10^{-10})5.0^2/2=2.5\times10^{-9}')+' Jが全てコイルにある。3を選ぶ。Lは最大電流を決めるが、問われる全エネルギーは初期条件から決まる。','LC振動の電気・磁気エネルギー交換','無散逸振動、コンデンサーとコイルのエネルギー、最大値の時点。',['lc','energy'],concept='concept_039',calc=True,citations=['mit_em11'])
add('R05-REG-APPLIED-03','電荷を固定した平行平板の間隔と誘電率を変え、極板間引力の比を選ぶ。',{'初期':'真空、間隔d、帯電量Q、引力F0。','変更':'間隔5d、比誘電率5の誘電体で全間隙を満たす。','固定量':'Qは変わらない。','モデル':'同じ面積A、端効果なし、一様な線形誘電体。'},[m(s) for s in ['F=F_0/25','F=F_0/5','F=F_0','F=5F_0','F=25F_0']],['固定Qで引力は間隔に依存しないため、距離の逆二乗だけを使うのは違う。','F=Q²/(2εA)でεが5倍となり1/5である。','εの増加による引力減少を無視している。','固定Qでは引力はεに反比例し、比例ではない。','電荷固定の平板モデルでは25倍となる要因はない。'],2,'固定Qのエネルギーは'+m(r'U=Q^2/(2C)=Q^2d/(2\varepsilon A)')+'であり、間隔方向の引力の大きさは'+m(r'F=\partial U/\partial d=Q^2/(2\varepsilon A)')+'となる。εが5ε0へ変わるのでF=F0/5、2である。間隔5倍で容量は初期と同じになるが、力はエネルギーの間隔微分であり同じとは限らない。','固定電荷のエネルギー微分と静電力','容量、固定する量、平板近似、力とエネルギーの微分。',['force','capacitor'],calc=True,citations=['mit_em05'])
add('R06-REG-APPLIED-04','静電場、磁場中の運動、誘導、エネルギー流の説明で最も不適切なものを選ぶ。',{'方向':'最も不適切。','導体':'孤立導体球を帯電させた静電平衡。','運動':'磁場に垂直な初速度、磁場以外の力なし。'},['点電荷間の力は距離の二乗に反比例する。','帯電導体球の内部電場は中心からの距離の二乗に反比例する。','磁場に垂直な速度を持つ荷電粒子は、速度に垂直な力で円運動する。','起電力の大きさは回路を貫く磁束の時間変化率に比例する。','ポインティングベクトルはエネルギー流の密度で、電場・磁場に垂直である。'],['クーロン力の逆二乗則に一致する。','静電平衡の導体内部はE=0である。逆二乗場は孤立球の外側の説明である。','qv×Bは速度へ垂直で速さを変えず、向きを変える。','ファラデーの法則の大きさに一致する。','S=E×Hでエネルギー流密度W/m²を表し、外積なので双方へ垂直である。'],2,'導体内に非零の電場が残ると自由電荷が移動して平衡ではなくなる。静電平衡では内部電場は0で、表面の外側には点電荷に相当する逆二乗場がある。内外を入れ替えた2を選ぶ。磁気力は仕事をせず、エネルギー輸送はポインティングベクトルで記述する。','静電平衡導体の内外と電磁場','導体遮蔽、クーロン則、ローレンツ力、磁束、外積と流密度。',['gauss','lorentz','poynting'],concept='concept_038',verdicts=['適切','不適切','適切','適切','適切'],citations=['mit_em04','mit_em13','mit_lorentz'])
add('R07-REG-APPLIED-04','磁性体で満たしたソレノイド内部の磁束密度を計算する。',{'長さ':'40 cm=0.40 m','全巻数':'150','比透磁率':'100','電流':'1.5 A','磁気定数':m(r'4\pi\times10^{-7}')+' T·m/A','モデル':'長いソレノイドの内部近似。比透磁率は与えられた値を使用。'},[m(s)+' mT' for s in [r'2.8\times10^{-3}',r'1.4\times10^{-1}',r'1.1\times10^1',r'7.1\times10^1',r'1.1\times10^2']],['与えられた透磁率・巻数密度では約70.7 mTであり一致しない。','透磁率と巻数密度を含めた70.7 mTと一致しない。','約70.7 mTより小さく、全巻数を単位長さ巻数へ換算する必要がある。','B=μ0μr(N/ℓ)Iから約70.7 mTで最も近い。','同じ計算では約70.7 mTで110 mTではない。'],4,'単位長さの巻数は150/0.40=375 m⁻¹である。'+m(r'B=\mu_0\mu_r(N/\ell)I=4\pi\times10^{-7}\times100\times375\times1.5')+'≃0.0707 T=70.7 mTなので4を選ぶ。端部や磁性体の非線形性はこの出題の近似へ含めず、与えられた比透磁率を用いる。','ソレノイドの巻数密度と磁束密度','アンペール則、透磁率、全巻数と巻数密度、cmとm、TとmT。',['solenoid'],concept='concept_038',calc=True,citations=['mit_em09'])
