(ROOT/'config/authored_batches/S7_011_electromagnetism.json').write_text(json.dumps(dict(batch_id='S7_011_electromagnetism',reference_date='2026-10-10',scope='応用理学電磁気27問。原典22頁画像の全条件・全5肢を確認し独立解答を保存後に公式と全問一致。電束/磁束、外力/電場仕事、固定Q/固定V、共振モデルを区別。',questions=items),ensure_ascii=False,indent=2)+'\n')
